SELECT id, supplier_name, country, city, MAX(rating) OVER w_ordered AS running_max_rating, MIN(rating) OVER w_ordered AS running_min_rating, AVG(rating) OVER w_ordered AS running_avg_rating, MAX(rating) OVER w_ordered_2 AS country_max_rating FROM suppliers WHERE rating BETWEEN 3.4 AND 3.9 WINDOW w_ordered AS (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered_2 AS (PARTITION BY country)
